// MasterLedgerInit.jsx
import React from 'react';
import './MasterLedgerInit.css';
import CompanyLogo from "../../../src/assets/gm_edited.jpg";

const MasterLedgerInit = ({ configData, onInitialize }) => {
  const {
    phmsa = true,
    trrc = true,
    material = 'Steel',
    type = 'Transmission',
    operatorName = 'Yunoya LTD',
  } = configData || {};

  const getRegulationText = () => {
    let regs = [];
    if (phmsa) regs.push('49 CFR Part 192');
    if (trrc) regs.push('TRRC (16 TAC)');
    return regs.length > 0 ? regs.join(' and ') : 'applicable regulations';
  };

  return (
    <div className="master-ledger-page">
      <div className="master-ledger-container">
        {/* Header */}
        <header className="init-header">
          <img src={CompanyLogo} alt="Galaxy Midstream" className="init-header-logo" />
          <div className="init-header-text">
            <span className="init-wordmark">GALAXY</span>
            <span className="init-wordmark-sub">COMPLIANCE SYSTEM</span>
          </div>
          <div className="init-header-meta">
            <i className="fas fa-terminal"></i>
            <span>SYSTEM INITIALIZATION</span>
          </div>
        </header>

        {/* Main Content */}
        <div className="master-ledger-content">
          <div className="icon-circle">
            <i className="fas fa-file-alt"></i>
          </div>

          <h1 className="master-title">GENERATE MASTER LEDGER</h1>

          <p className="master-description">
            We will now generate your site-specific compliance requirements based on{' '}
            <strong>{getRegulationText()}</strong> for a{' '}
            <strong>{material.toLowerCase()} {type.toLowerCase()} pipeline</strong>.
          </p>

          <button className="init-dashboard-btn" onClick={onInitialize}>
            INITIALIZE DASHBOARD
          </button>

          <p className="master-note">
            This process will populate your compliance ledger with requirements tailored to {operatorName}.
          </p>
        </div>
      </div>
    </div>
  );
};

export default MasterLedgerInit;
